import {distance,bearing,interpolate,solar,illumination} from './geometry.js';
export function demo(){return {schemaVersion:1,name:'高雄港外・晨間光照測試',departure:'2026-10-20T08:00',timezone:'Asia/Taipei',sampleMode:'distance',sampleStep:200,defaultSpeed:6,camera:{yaw:0,pitch:0,hfov:60,vfov:40},waypoints:[{lat:22.605,lng:120.255,wait:0,target:''},{lat:22.585,lng:120.233,wait:5,target:''},{lat:22.566,lng:120.25,wait:0,target:''},{lat:22.58,lng:120.271,wait:0,target:''}],segments:[{speed:6},{speed:8},{speed:6}]};}
export function validate(p){if(p.defaultSpeed===undefined)p.defaultSpeed=6;if(!Number.isFinite(p.defaultSpeed)||p.defaultSpeed<=0||p.defaultSpeed>100)throw Error('預設航速必須大於 0 且不超過 100 kt');if(p.schemaVersion!==1||!Array.isArray(p.waypoints)||p.waypoints.length>300||!Array.isArray(p.segments)||p.segments.length!==Math.max(0,p.waypoints.length-1))throw Error('專案版本或航線結構不正確');if(!Number.isFinite(Date.parse(p.departure+'+08:00')))throw Error('出發時間不正確');for(const w of p.waypoints)if(!Number.isFinite(w.lat)||Math.abs(w.lat)>85||!Number.isFinite(w.lng)||Math.abs(w.lng)>180||!Number.isFinite(w.wait)||w.wait<0||w.wait>1440||(w.target&&!Number.isFinite(Date.parse(w.target+'+08:00'))))throw Error('航點座標、停留或指定時間不正確');for(const s of p.segments)if(!(s.speed>0&&s.speed<=100))throw Error('航速必須大於 0 且不超過 100 kt');if(!['distance','time'].includes(p.sampleMode)||!(p.sampleStep>=10&&p.sampleStep<=10000))throw Error('取樣間隔需介於 10～10000');for(const k of ['yaw','pitch','hfov','vfov'])if(!Number.isFinite(p.camera?.[k]))throw Error('相機參數不正確');if(Math.abs(p.camera.yaw)>180||Math.abs(p.camera.pitch)>90||p.camera.hfov<=0||p.camera.hfov>=180||p.camera.vfov<=0||p.camera.vfov>=180)throw Error('相機角度超出範圍');return p;}
export function calculate(p){validate(p);let time=Date.parse(p.departure+'+08:00'),total=0;const legs=[],arrivals=[],samples=[];for(let i=0;i<p.waypoints.length;i++){const a=p.waypoints[i];arrivals.push(time);const depart=time+a.wait*60000;if(i===p.waypoints.length-1){time=depart;break;}const b=p.waypoints[i+1],length=distance(a,b),speed=p.segments[i].speed,duration=length/(speed*.514444),heading=bearing(a,b);legs.push({a,b,length,speed,heading,start:depart,end:depart+duration*1000,waitStart:time,index:i});total+=length;time=depart+duration*1000;}
 const start=Date.parse(p.departure+'+08:00');for(const leg of legs){const step=p.sampleMode==='distance'?p.sampleStep/(leg.speed*.514444):p.sampleStep;const n=Math.ceil((leg.end-leg.start)/1000/step);if(samples.length+n>10000)throw Error('取樣點超過 10000，請增大間隔');for(let j=0;j<=n;j++){const ms=Math.min(leg.end,leg.start+j*step*1000);samples.push(pointAt(p,{legs,start,end:time},ms,leg.index));}}
 return {legs,arrivals,samples,total,start,end:time};}
export function pointAt(p,result,ms,preferred){if(!result.legs.length)return null;let l=preferred===undefined?result.legs.find(x=>ms<=x.end):result.legs[preferred];l??=result.legs.at(-1);const f=Math.max(0,Math.min(1,(ms-l.start)/(l.end-l.start||1))),pos=interpolate(l.a,l.b,f),sun=solar(ms,pos.lat,pos.lng),waiting=ms<l.start||ms>result.legs.at(-1).end;return {...pos,time:ms,heading:l.heading,speed:waiting?0:l.speed,waiting,leg:l.index,...sun,...illumination(sun,l.heading,p.camera)};}
